-- Corrections menuiseries + intégration Airwell Wellea demandée le 23/10/2026.
-- Idempotent : une référence fabricant donnée n'est jamais insérée deux fois.

-- Le châssis fixe est une baie fixe autorisée par BAR-EN-104 : ses performances Uw/Sw restent à renseigner.
UPDATE public.catalogue_produits
SET eligible_cee = true,
    fiche_cee = 'BAR-EN-104'
WHERE upper(coalesce(reference,'')) IN ('MEN-PVC-FIXE','MEN-PVC-FIXE-M2')
   OR lower(coalesce(nom,'')) LIKE '%châssis fixe pvc%';

-- Les volets roulants isolants relèvent de BAR-EN-108 (ΔR > 0,22 m².K/W), pas de BAR-EN-104.
UPDATE public.catalogue_produits
SET eligible_cee = true,
    fiche_cee = 'BAR-EN-108'
WHERE lower(coalesce(nom,'')) LIKE '%volet roulant%'
   OR lower(coalesce(marque,'')) = 'bubendorff';

-- Les portes d'entrée ne relèvent pas de BAR-EN-104. Pas de fiche CEE standardisée spécifique identifiée pour la porte d'entrée seule.
UPDATE public.catalogue_produits
SET eligible_cee = false, fiche_cee = NULL
WHERE categorie = 'menuiseries_portes'
   OR lower(coalesce(nom,'')) ~ 'porte d.entree|porte entree';

