  LOOP
    SELECT id INTO found_id FROM public.catalogue_produits
      WHERE upper(coalesce(reference,'')) = upper(item->>'reference')
      LIMIT 1;
    IF found_id IS NULL THEN
      INSERT INTO public.catalogue_produits
        (categorie, nom, marque, reference, description, unite, prix_unitaire_ht, tva_taux,
         eligible_mpr, eligible_cee, fiche_cee, caracteristiques, actif, forfait_pose_ht, forfait_evacuation_ht, forfait_consommables_ht)
      VALUES
        (item->>'categorie', item->>'nom', item->>'marque', item->>'reference', item->>'description',
         coalesce(item->>'unite','unite'), (item->>'prix_unitaire_ht')::numeric, (item->>'tva_taux')::numeric,
         (item->>'eligible_mpr')::boolean, (item->>'eligible_cee')::boolean, nullif(item->>'fiche_cee',''),
         coalesce(item->'caracteristiques','{}'::jsonb), true, 0, 0, 0);
    ELSE
      UPDATE public.catalogue_produits SET
        categorie = item->>'categorie', nom = item->>'nom', marque = item->>'marque',
        description = item->>'description', unite = coalesce(item->>'unite','unite'),
        prix_unitaire_ht = (item->>'prix_unitaire_ht')::numeric, tva_taux = (item->>'tva_taux')::numeric,
        eligible_mpr = (item->>'eligible_mpr')::boolean, eligible_cee = (item->>'eligible_cee')::boolean,
        fiche_cee = nullif(item->>'fiche_cee',''), caracteristiques = coalesce(item->'caracteristiques','{}'::jsonb), actif = true
      WHERE id = found_id;
    END IF;
    found_id := NULL;
  END LOOP;
END $$;
